q(1,"Em “O suspeito fugiu pela rua lateral”, o verbo está no modo",["indicativo, pois apresenta o fato como certo.","subjuntivo, pois expressa hipótese.","imperativo, pois expressa ordem.","infinitivo, pois é o nome do verbo.","gerúndio, pois indica ação em curso."],"O indicativo apresenta o fato como certo: ele fugiu.")
