q(1,"Em “Desligue o motor, por favor”, o verbo expressa",["pedido ou ordem, no modo imperativo.","fato certo, no modo indicativo.","hipótese, no modo subjuntivo.","ação passada concluída.","ação futura certa."],"O imperativo expressa ordem, pedido ou conselho.")
q(1,"Em “A equipe atendeu a ocorrência às 22h”, o tempo verbal indica ação",["concluída no passado.","habitual no passado.","anterior a outra ação passada.","futura.","hipotética."],"Pretérito perfeito: ação terminada.")
q(1,"Em “O comerciante fechava a loja às 19h todos os dias”, o pretérito imperfeito indica",["hábito no passado.","ação concluída de uma só vez.","ação futura.","ordem.","dúvida."],"O imperfeito apresenta ação contínua ou repetida no passado.")
q(1,"Assinale a frase com verbo no futuro do presente.",["A operação começará amanhã.","A operação começaria amanhã.","A operação começou ontem.","A operação começava cedo.","Que a operação comece logo."],"Começará: futuro do presente. Começaria é futuro do pretérito; começou, perfeito; começava, imperfeito; comece, presente do subjuntivo.")
q(1,"Assinale a forma que completa corretamente: “Se o guarda ____ o suspeito, deve avisar a central.”",["vir","ver","vier","verá","vendo"],"Futuro do subjuntivo de ver: se ele vir. “Vier” é do verbo vir (chegar).")
q(1,"Assinale a forma que completa corretamente: “Quando você ____ a mochila no chão, afaste-se.”",["puser","por","pôr","pusesse","ponha"],"Futuro do subjuntivo de pôr: quando você puser.")
q(1,"Assinale a forma correta: “Ontem, o guarda ____ na briga.”",["interveio","interviu","interveu","intervisse","intervido"],"Intervir segue vir: ele veio, ele interveio.")
