q(1,"Em “A rua estava muito escura”, o advérbio “muito” modifica",["o adjetivo “escura”, intensificando-o.","o substantivo “rua”.","o verbo “estava”.","outro advérbio.","a oração inteira."],"“Muito” intensifica a qualidade “escura”.")
q(1,"Em “Naquela noite, o guarda entra na loja e encontra o caixa aberto”, o presente do indicativo é usado para",["narrar um fato passado de modo mais vivo.","indicar um hábito.","indicar um fato futuro.","expressar dúvida.","dar uma ordem."],"É o presente histórico: o fato é passado (“naquela noite”), mas o presente aproxima o leitor da cena.")
