from collections import Counter; print(Counter(x['n'] for x in Q))
for x in Q: assert len(x['a'])==5 and len(set(x['a']))==5, x['e']
L=[]
for i,x in enumerate(Q,1):
    s='{id:"p7-%02d",n:%d,'%(i,x['n'])+('tx:"%s",'%x['tx'] if x['tx'] else '')+'e:%s,a:%s,c:%s}'%(json.dumps(x['e'],ensure_ascii=False),json.dumps(x['a'],ensure_ascii=False),json.dumps(x['c'],ensure_ascii=False))
    L.append(s)
open('banco.js','w').write('BANCO["pt-7"] = [\n'+',\n'.join(L)+'\n];')
tj="<strong>Comerciante tem loja arrombada pela segunda vez no mês</strong><br><br>Uma loja de eletrônicos do centro foi arrombada na madrugada de ontem. Quando a equipe da Guarda Municipal chegou, por volta das 3h, os autores já haviam deixado o local. Segundo vizinhos, eles teriam fugido em um carro escuro.<br><br>Foram levados celulares e um computador. O proprietário, que fechava a loja todos os dias às 19h, contou que instalara um alarme na semana anterior, mas o aparelho não disparou.<br><br>A Guarda informou que as imagens das câmeras da rua serão analisadas nos próximos dias. Se os autores forem identificados, o caso seguirá para a Polícia Civil."
tk="<strong>A pressa da avenida</strong><br><br>Todo fim de tarde, a avenida vira um teste de paciência. Os motoristas avançam lentamente, buzinam sem parar e, quase sempre, culpam alguém que nem está ali. Felizmente, há quem prefira esperar com calma.<br><br>Ontem, um senhor parou o carro bem perto da faixa e fez sinal para uma criança atravessar. Ela cruzou depressa, meio assustada, e agradeceu de longe. Ninguém buzinou naquele instante.<br><br>Talvez a cidade mude quando mais gente entender que chegar dois minutos depois raramente é um problema. Atravessar a rua com medo, sim."
open('textos.js','w').write(',\ntj: '+json.dumps(tj,ensure_ascii=False)+',\ntk: '+json.dumps(tk,ensure_ascii=False))
